import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"অন্ধকার প্রতিস্থাপনকারীর চার শাখা নিষ্পত্তি","description":"","frontmatter":{},"headers":[],"relativePath":"bn/0059-黑暗置换体四类分支处置.md","filePath":"bn/0059-黑暗置换体四类分支处置.md"}'),h={name:"bn/0059-黑暗置换体四类分支处置.md"};function l(o,t,i,n,s,b){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="অন্ধকার-প্রতিস্থাপনকারীর-চার-শাখা-নিষ্পত্তি" tabindex="-1">অন্ধকার প্রতিস্থাপনকারীর চার শাখা নিষ্পত্তি <a class="header-anchor" href="#অন্ধকার-প্রতিস্থাপনকারীর-চার-শাখা-নিষ্পত্তি" aria-label="Permalink to &quot;অন্ধকার প্রতিস্থাপনকারীর চার শাখা নিষ্পত্তি&quot;">​</a></h1><table tabindex="0"><thead><tr><th>আইটেম</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>59</td></tr><tr><td>মডিউল</td><td>জাতি ও জীবন রূপ</td></tr><tr><td>মূল কীওয়ার্ড</td><td>মিলন সিম্বায়োসিস, বিচ্ছিন্নতা বসতি স্থাপন, সীলমোহর পর্যবেক্ষণ, বিলুপ্তি, শাখা নিষ্পত্তি</td></tr></tbody></table><h2 id="১-শাখা-নিষ্পত্তির-সামগ্রিক-কাঠামো" tabindex="-1">১. শাখা নিষ্পত্তির সামগ্রিক কাঠামো <a class="header-anchor" href="#১-শাখা-নিষ্পত্তির-সামগ্রিক-কাঠামো" aria-label="Permalink to &quot;১. শাখা নিষ্পত্তির সামগ্রিক কাঠামো&quot;">​</a></h2><p>অন্ধকার প্রতিস্থাপনকারীর নিষ্পত্তি হলো অ্যাঙ্কর সিম্বায়োসিস সভ্যতার জীবন পরিচালনার সবচেয়ে জটিল ক্ষেত্র। অদ্ভুত জীবন ও অদ্ভুত শক্তির তিন শ্রেণীর নিষ্পত্তি প্রক্রিয়া থেকে আলাদা, অন্ধকার প্রতিস্থাপনকারী দ্বৈত আত্মা সহাবস্থানের বিশেষ কাঠামো জড়িত (বিস্তারিত &quot;৫৭-অন্ধকার প্রতিস্থাপনকারীর উৎপত্তি ও মূল সত্তা&quot; দেখুন) হওয়ায়, আরও সূক্ষ্ম শাখা নিষ্পত্তি পরিকল্পনার প্রয়োজন হয়। &quot;৫৮-দ্বৈত আত্মা নৈতিক নীতি&quot; দ্বারা প্রতিষ্ঠিত নৈতিক নীতি অনুযায়ী, অন্ধকার প্রতিস্থাপনকারীর বিকাশের পর্যায়, মূল মালিক আত্মার অবস্থা, অন্ধকার আত্মার বৈশিষ্ট্য ও ঝুঁকির মাত্রার সাথে মিলিয়ে, অন্ধকার প্রতিস্থাপনকারীর নিষ্পত্তি চার শাখায় বিভক্ত: মিলন সিম্বায়োসিস ধরন, বিচ্ছিন্নতা বসতি স্থাপন ধরন, সীলমোহর পর্যবেক্ষণ ধরন, বিলুপ্তি ধরন।</p><p>চার শাখা নিষ্পত্তির নির্বাচন নিম্নলিখিত সিদ্ধান্তের যুক্তি অনুসরণ করে:</p><table tabindex="0"><thead><tr><th>সিদ্ধান্তের কারণ</th><th>বিবেচনার বিষয়</th></tr></thead><tbody><tr><td>বিকাশের পর্যায়</td><td>প্রথম থেকে তৃতীয় পর্যায়ে রক্ষাকে অগ্রাধিকার দেওয়া হয়, চতুর্থ পর্যায়ে সতর্কতার সাথে মূল্যায়ন করা হয়, পঞ্চম পর্যায়ে মূল মালিক ইতিমধ্যে বিলীন</td></tr><tr><td>মূল মালিক আত্মার অবস্থা</td><td>মূল মালিক আত্মা এখনও বিদ্যমান কিনা, ইচ্ছা প্রকাশ করতে পারে কিনা, পুনরুদ্ধারের সম্ভাবনা আছে কিনা</td></tr><tr><td>অন্ধকার আত্মার বৈশিষ্ট্য</td><td>অন্ধকার আত্মার যোগাযোগের সম্ভাবনা আছে কিনা, রূপান্তরের সুযোগ আছে কিনা, বিনাশকারীতার মাত্রা</td></tr><tr><td>ঝুঁকির মাত্রা</td><td>গণসুরক্ষা ও অন্যের অধিকারের হুমকির মাত্রা</td></tr><tr><td>নৈতিক পর্যালোচনার সিদ্ধান্ত</td><td>দ্বৈত আত্মা নৈতিক পর্যালোচনা কমিটির পর্যালোচনার মতামত ও সিদ্ধান্ত</td></tr><tr><td>মূল মালিকের ইচ্ছা</td><td>মূল মালিক আত্মা ইচ্ছা প্রকাশ করতে সক্ষম অবস্থায় যে পছন্দ করে</td></tr></tbody></table><h2 id="২-প্রথম-শ্রেণী-মিলন-সিম্বায়োসিস-ধরনের-নিষ্পত্তি" tabindex="-1">২. প্রথম শ্রেণী: মিলন সিম্বায়োসিস ধরনের নিষ্পত্তি <a class="header-anchor" href="#২-প্রথম-শ্রেণী-মিলন-সিম্বায়োসিস-ধরনের-নিষ্পত্তি" aria-label="Permalink to &quot;২. প্রথম শ্রেণী: মিলন সিম্বায়োসিস ধরনের নিষ্পত্তি&quot;">​</a></h2><p>মিলন সিম্বায়োসিস ধরনের নিষ্পত্তি হলো চার শাখার মধ্যে সবচেয়ে সক্রিয় ও সবচেয়ে গঠনমূলক নিষ্পত্তির পদ্ধতি, যা মূল মালিক আত্মা ও অন্ধকার আত্মার মধ্যে মৈত্রী স্থাপন ও আত্মা মিলন বাস্তবায়নের সম্ভাবনা থাকা অন্ধকার প্রতিস্থাপনকারীদের জন্য প্রযোজ্য।</p><h3 id="১-প্রযোজ্য-শর্ত" tabindex="-1">(১) প্রযোজ্য শর্ত <a class="header-anchor" href="#১-প্রযোজ্য-শর্ত" aria-label="Permalink to &quot;(১) প্রযোজ্য শর্ত&quot;">​</a></h3><p>মিলন সিম্বায়োসিস ধরনের নিষ্পত্তি অবশ্যই একই সাথে নিম্নলিখিত শর্তগুলি পূরণ করতে হবে:</p><p>১. অন্ধকার প্রতিস্থাপনকারী তৃতীয় পর্যায়ে (দ্বৈত আত্মা গঠনকাল) বা চতুর্থ পর্যায়ের প্রারম্ভিক অবস্থায় (অন্ধকার প্রধানকালের প্রারম্ভে), মূল মালিক আত্মা বিদ্যমান এবং নির্দিষ্ট স্বায়ত্তশাসিত চেতনা রয়েছে। ২. মূল মালিক আত্মা স্পষ্টভাবে অন্ধকার আত্মার সাথে মিলনের চেষ্টা করার ইচ্ছা প্রকাশ করেছে, এবং该 ইচ্ছা প্রকৃত, স্বায়ত্তশাসিত হিসেবে স্বীকৃত হয়েছে। ৩. অন্ধকার আত্মার নির্দিষ্ট যোগাযোগ ক্ষমতা রয়েছে, সম্পূর্ণ বিনাশকারী নয় এমন বৈশিষ্ট্য প্রদর্শন করে, মিলন গ্রহণের সম্ভাবনা রয়েছে। ৪. ঝুঁকির মাত্রার মূল্যায়ন দ্বিতীয় স্তরে (মাঝারি ঝুঁকি) বা তার নিচে, মিলন প্রক্রিয়া গণসুরক্ষার জন্য অনিয়ন্ত্রিত হুমকি তৈরি করবে না। ৫. দ্বৈত আত্মা নৈতিক পর্যালোচনা কমিটির পর্যালোচনা ও অনুমোদন।</p><h3 id="২-নিষ্পত্তির-লক্ষ্য" tabindex="-1">(২) নিষ্পত্তির লক্ষ্য <a class="header-anchor" href="#২-নিষ্পত্তির-লক্ষ্য" aria-label="Permalink to &quot;(২) নিষ্পত্তির লক্ষ্য&quot;">​</a></h3><p>মূল মালিক আত্মা ও অন্ধকার আত্মার মৈত্রী স্থাপনে পরিচালনা করার মাধ্যমে, দুটি আত্মার জৈব মিলন বাস্তবায়ন করা, মূল মালিকের স্মৃতি, ব্যক্তিত্ব ও অন্ধকার শক্তি সমন্বিত একটি নতুন আত্মা গঠন করা। মিলনের পরের নতুন আত্মা মূল মালিকের নাগরিক পরিচয় ও বৈধ অধিকার ধরে রাখে, একই সাথে অন্ধকার শক্তি নিয়ন্ত্রণের ক্ষমতা অর্জন করে, সিম্বায়োসিস সভ্যতার বিশেষ সদস্য হয়ে ওঠে।</p><h3 id="৩-নিষ্পত্তির-পদক্ষেপ" tabindex="-1">(৩) নিষ্পত্তির পদক্ষেপ <a class="header-anchor" href="#৩-নিষ্পত্তির-পদক্ষেপ" aria-label="Permalink to &quot;(৩) নিষ্পত্তির পদক্ষেপ&quot;">​</a></h3><table tabindex="0"><thead><tr><th>পদক্ষেপ</th><th>নাম</th><th>নির্দিষ্ট বিষয়বস্তু</th><th>দায়িত্বপ্রাপ্ত প্রতিষ্ঠান</th></tr></thead><tbody><tr><td>প্রথম পদক্ষেপ</td><td>নৈতিক পর্যালোচনা</td><td>দ্বৈত আত্মা নৈতিক পর্যালোচনা কমিটি মিলন পরিকল্পনার সম্পূর্ণ পর্যালোচনা করে, নৈতিক নীতি অনুযায়ী কনফার্ম করে</td><td>দ্বৈত আত্মা নৈতিক পর্যালোচনা কমিটি</td></tr><tr><td>দ্বিতীয় পদক্ষেপ</td><td>যোগাযোগ পরিচালনা</td><td>নিয়ন্ত্রিত পরিবেশে, পেশাদার আত্মা পরিচালক মূল মালিক আত্মা ও অন্ধকার আত্মার যোগাযোগে সহায়তা করে, পারস্পরিক বোঝাপড়া প্রচার করে</td><td>আত্মা চিকিৎসা কেন্দ্র + সাধক</td></tr><tr><td>তৃতীয় পদক্ষেপ</td><td>মৈত্রী আলোচনা</td><td>দুটি আত্মাকে মিলনের পরের পরিচয়, স্মৃতি, ক্ষমতা, আচরণ নীতি ইত্যাদি নিয়ে মৈত্রী চুক্তিতে পৌঁছাতে পরিচালনা করা</td><td>আত্মা চিকিৎসা কেন্দ্র + আইনি পরামর্শদাতা</td></tr><tr><td>চতুর্থ পদক্ষেপ</td><td>মিলন প্রস্তুতি</td><td>মিলনের পূর্বে শরীরের পরিচর্যা, শক্তি ভারসাম্য, মানসিক নির্মাণ ইত্যাদি প্রস্তুতি কাজ করা</td><td>চিকিৎসা দল + সাধন নির্দেশক</td></tr><tr><td>পঞ্চম পদক্ষেপ</td><td>আত্মা মিলন</td><td>উচ্চকক্ষের সাধক ও আত্মা চিকিৎসকের যৌথ সহায়তায়, আত্মা মিলন অস্ত্রোপচার/আচার প্রয়োগ করা</td><td>উচ্চকক্ষের সাধক + আত্মা চিকিৎসক</td></tr><tr><td>ষষ্ঠ পদক্ষেপ</td><td>মিলনের পরের স্থিতিশীলতা</td><td>মিলনের পরের নতুন আত্মার স্থিতিশীলকরণ প্রক্রিয়া করা, আত্মার সম্পূর্ণতা ও শরীরের অভিযোজন পর্যবেক্ষণ করা</td><td>চিকিৎসা দল + পর্যবেক্ষণ দল</td></tr><tr><td>সপ্তম পদক্ষেপ</td><td>পরিচয় নিশ্চিতকরণ</td><td>মিলনের পরের নতুন আত্মার পরিচয় নিশ্চিত করা, মূল মালিকের নাগরিক পরিচয় ধরে রাখা, পরিচয় ফাইল আপডেট করা</td><td>নিবন্ধন ব্যবস্থাপনা প্রতিষ্ঠান + জীবন ব্যবস্থাপনা ব্যুরো</td></tr><tr><td>অষ্টম পদক্ষেপ</td><td>একীকরণ সহায়তা</td><td>মিলনের পরের ব্যক্তির জন্য মানসিক পরামর্শ, সাধন নির্দেশনা, সামাজিক একীকরণ ইত্যাদি সহায়তা সেবা প্রদান করা</td><td>সকল জাতির বিষয়ক দপ্তর + সম্প্রদায়</td></tr><tr><td>নবম পদক্ষেপ</td><td>দীর্ঘমেয়াদী ট্র্যাকিং</td><td>মিলন ব্যক্তির উপর কমপক্ষে পাঁচ বছরের দীর্ঘমেয়াদী ট্র্যাকিং পর্যবেক্ষণ করা, মিলনের স্থিতিশীলতা ও সামাজিক অভিযোজন মূল্যায়ন করা</td><td>জীবন ব্যবস্থাপনা ব্যুরো + সম্প্রদায়</td></tr></tbody></table><h3 id="৪-মিলনের-পরের-ব্যবস্থাপনা" tabindex="-1">(৪) মিলনের পরের ব্যবস্থাপনা <a class="header-anchor" href="#৪-মিলনের-পরের-ব্যবস্থাপনা" aria-label="Permalink to &quot;(৪) মিলনের পরের ব্যবস্থাপনা&quot;">​</a></h3><p>মিলনের পরের ব্যক্তি যদিও মূল মালিকের নাগরিক পরিচয় ধরে রাখে, তবুও বিশেষ ব্যবস্থাপনা গ্রহণ করতে হবে:</p><ul><li><strong>শক্তি ব্যবস্থাপনা</strong>: মিলন ব্যক্তির অন্ধকার শক্তি ব্যবহার কঠোরভাবে নিয়ন্ত্রিত হয়, নিয়মিত শক্তি পরীক্ষা করতে হবে, পাবলিক প্লেসে অন্ধকার শক্তি ব্যবহার নিষিদ্ধ।</li><li><strong>আচরণ পর্যবেক্ষণ</strong>: মিলন ব্যক্তিকে নিয়মিত জীবন ব্যবস্থাপনা ব্যুরোতে আচরণের অবস্থা রিপোর্ট করতে হবে, সম্প্রদায়ের পর্যবেক্ষণ ও সহায়তা গ্রহণ করতে হবে।</li><li><strong>সাধন সীমাবদ্ধতা</strong>: মিলন ব্যক্তি অন্ধকার বৈশিষ্ট্যকে তীব্র করতে পারে এমন সাধনা করতে পারবে না, সাধন পরিকল্পনা অনুমোদনের অধীন হবে।</li><li><strong>জরুরি পরিকল্পনা</strong>: মিলন ব্যক্তির অন্ধকার নিয়ন্ত্রণহীনতার জরুরি পরিকল্পনা প্রতিষ্ঠা করা, নিয়ন্ত্রণহীনতার লক্ষণ দেখা দিলে অবিলম্বে নিয়ন্ত্রণ শুরু করা।</li><li><strong>প্রত্যাহার ব্যবস্থা</strong>: মিলনের পরে গুরুতর অস্থিরতা বা ক্রমাগত বিপজ্জনক আচরণ দেখা দিলে, পুনর্মূল্যায়ন করে অন্য নিষ্পত্তি ধরনে রূপান্তর করা যায়।</li></ul><h3 id="৫-মিলন-ব্যর্থতার-পরিচালনা" tabindex="-1">(৫) মিলন ব্যর্থতার পরিচালনা <a class="header-anchor" href="#৫-মিলন-ব্যর্থতার-পরিচালনা" aria-label="Permalink to &quot;(৫) মিলন ব্যর্থতার পরিচালনা&quot;">​</a></h3><p>আত্মা মিলনে ব্যর্থতার ঝুঁকি রয়েছে, মিলন ব্যর্থতার পরিচালনা পরিকল্পনা:</p><ul><li><strong>মিলন ব্যাহত</strong>: মিলন প্রক্রিয়ায় গুরুতর অস্থিরতা দেখা দিলে, অবিলম্বে মিলন ব্যাহত করা, দুটি আত্মাকে মিলনের পূর্ববর্তী অবস্থায় ফিরিয়ে আনা।</li><li><strong>মিলন অসম্পূর্ণ</strong>: মিলনের পরে আত্মার অসম্পূর্ণতা বা ব্যক্তিত্ব বিভাজন দেখা দিলে, পরবর্তী পরিচালনার জন্য বিচ্ছিন্নতা বসতি স্থাপন ধরনের নিষ্পত্তিতে স্থানান্তর করা।</li><li><strong>মিলন নিয়ন্ত্রণহীন</strong>: মিলনের পরে নতুন আত্মা অনিয়ন্ত্রিত বিনাশকারীতা প্রদর্শন করলে, অবিলম্বে সীলমোহর পর্যবেক্ষণ ধরন বা বিলুপ্তি ধরনের নিষ্পত্তিতে স্থানান্তর করা।</li></ul><h2 id="৩-দ্বিতীয়-শ্রেণী-বিচ্ছিন্নতা-বসতি-স্থাপন-ধরনের-নিষ্পত্তি" tabindex="-1">৩. দ্বিতীয় শ্রেণী: বিচ্ছিন্নতা বসতি স্থাপন ধরনের নিষ্পত্তি <a class="header-anchor" href="#৩-দ্বিতীয়-শ্রেণী-বিচ্ছিন্নতা-বসতি-স্থাপন-ধরনের-নিষ্পত্তি" aria-label="Permalink to &quot;৩. দ্বিতীয় শ্রেণী: বিচ্ছিন্নতা বসতি স্থাপন ধরনের নিষ্পত্তি&quot;">​</a></h2><p>বিচ্ছিন্নতা বসতি স্থাপন ধরনের নিষ্পত্তি মূল মালিক আত্মা ও অন্ধকার আত্মা মিলন করতে পারে না কিন্তু বিচ্ছিন্ন করতে পারে এমন অন্ধকার প্রতিস্থাপনকারীদের জন্য প্রযোজ্য, আত্মা বিচ্ছিন্নতা অস্ত্রোপচারের মাধ্যমে দুটি আত্মাকে আলাদা করে, আলাদাভাবে বসতি স্থাপন করা হয়।</p><h3 id="১-প্রযোজ্য-শর্ত-1" tabindex="-1">(১) প্রযোজ্য শর্ত <a class="header-anchor" href="#১-প্রযোজ্য-শর্ত-1" aria-label="Permalink to &quot;(১) প্রযোজ্য শর্ত&quot;">​</a></h3><p>১. অন্ধকার প্রতিস্থাপনকারী তৃতীয় পর্যায়ে বা চতুর্থ পর্যায়ে, মূল মালিক আত্মা বিদ্যমান এবং পুনরুদ্ধারের সম্ভাবনা রয়েছে। ২. দুটি আত্মার মিলনের চেষ্টা ব্যর্থ হয়েছে বা মিলনের শর্ত নেই। ৩. প্রযুক্তিগত মূল্যায়নে আত্মা বিচ্ছিন্নতা সম্ভব বলে মনে করা হয়েছে, বিচ্ছিন্নতার পর মূল মালিক আত্মা স্বাধীনভাবে বেঁচে থাকতে পারবে। ৪. মূল মালিক আত্মা স্পষ্টভাবে বিচ্ছিন্নতার ইচ্ছা প্রকাশ করেছে। ৫. দ্বৈত আত্মা নৈতিক পর্যালোচনা কমিটির পর্যালোচনা ও অনুমোদন।</p><h3 id="২-নিষ্পত্তির-লক্ষ্য-1" tabindex="-1">(২) নিষ্পত্তির লক্ষ্য <a class="header-anchor" href="#২-নিষ্পত্তির-লক্ষ্য-1" aria-label="Permalink to &quot;(২) নিষ্পত্তির লক্ষ্য&quot;">​</a></h3><p>আত্মা বিচ্ছিন্নতা অস্ত্রোপচারের মাধ্যমে মূল মালিক আত্মা ও অন্ধকার আত্মাকে আলাদা করা, মূল মালিক আত্মা শরীরে ফিরিয়ে স্বাভাবিক জীবনে ফিরিয়ে আনা, অন্ধকার আত্মা বিশেষ পাত্র বা সুবিধায় বসতি স্থাপন করে নিয়ন্ত্রণ ও গবেষণা করা।</p><h3 id="৩-নিষ্পত্তির-পদক্ষেপ-1" tabindex="-1">(৩) নিষ্পত্তির পদক্ষেপ <a class="header-anchor" href="#৩-নিষ্পত্তির-পদক্ষেপ-1" aria-label="Permalink to &quot;(৩) নিষ্পত্তির পদক্ষেপ&quot;">​</a></h3><table tabindex="0"><thead><tr><th>পদক্ষেপ</th><th>নাম</th><th>নির্দিষ্ট বিষয়বস্তু</th><th>দায়িত্বপ্রাপ্ত প্রতিষ্ঠান</th></tr></thead><tbody><tr><td>প্রথম পদক্ষেপ</td><td>নৈতিক পর্যালোচনা</td><td>দ্বৈত আত্মা নৈতিক পর্যালোচনা কমিটি বিচ্ছিন্নতা পরিকল্পনার পর্যালোচনা করে, বিচ্ছিন্নতার প্রয়োজনীয়তা ও সম্ভাব্যতা কনফার্ম করে</td><td>দ্বৈত আত্মা নৈতিক পর্যালোচনা কমিটি</td></tr><tr><td>দ্বিতীয় পদক্ষেপ</td><td>বিচ্ছিন্নতা প্রস্তুতি</td><td>বিচ্ছিন্নতার পূর্বে শরীরের মূল্যায়ন, আত্মার অবস্থা সনাক্তকরণ, শক্তি ভারসাম্য সমন্বয় ইত্যাদি প্রস্তুতি কাজ করা</td><td>চিকিৎসা দল + আত্মা চিকিৎসক</td></tr><tr><td>তৃতীয় পদক্ষেপ</td><td>আত্মা বিচ্ছিন্নতা</td><td>উচ্চকক্ষের সাধক ও আত্মা চিকিৎসকের সহায়তায়, আত্মা বিচ্ছিন্নতা অস্ত্রোপচার প্রয়োগ করা, দুটি আত্মাকে শরীর থেকে আলাদা করা</td><td>উচ্চকক্ষের সাধক + আত্মা চিকিৎসক</td></tr><tr><td>চতুর্থ পদক্ষেপ</td><td>মূল মালিক ফিরিয়ে আনা</td><td>মূল মালিক আত্মাকে পুনরায় শরীরে প্রতিস্থাপন করা, আত্মা স্থিতিশীলকরণ ও শরীর পুনর্বাসন চিকিৎসা করা</td><td>চিকিৎসা দল</td></tr><tr><td>পঞ্চম পদক্ষেপ</td><td>অন্ধকার বসতি স্থাপন</td><td>বিচ্ছিন্ন অন্ধকার আত্মাকে বিশেষ আত্মা কন্টেইনমেন্ট পাত্রে বসতি স্থাপন করা, আত্মা সংরক্ষণ সুবিধায় সংরক্ষণ করা</td><td>জীবন ব্যবস্থাপনা ব্যুরো + প্রযুক্তি দল</td></tr><tr><td>ষষ্ঠ পদক্ষেপ</td><td>মূল মালিক পুনর্বাসন</td><td>মূল মালিকের সম্পূর্ণ শরীর পুনর্বাসন, মানসিক চিকিৎসা, সাধন পুনরুদ্ধার করা, তাকে স্বাভাবিক জীবনে ফিরিয়ে আনতে সহায়তা করা</td><td>চিকিৎসা দল + মানসিক পরামর্শদাতা</td></tr><tr><td>সপ্তম পদক্ষেপ</td><td>পরিচয় পুনরুদ্ধার</td><td>মূল মালিকের পরিচয় ও অধিকার সম্পূর্ণরূপে পুনরুদ্ধার কনফার্ম করা, পরিচয় ফাইল আপডেট করা</td><td>নিবন্ধন ব্যবস্থাপনা প্রতিষ্ঠান</td></tr><tr><td>অষ্টম পদক্ষেপ</td><td>অন্ধকার আত্মা ব্যবস্থাপনা</td><td>বিচ্ছিন্ন অন্ধকার আত্মা ক্রমাগত পর্যবেক্ষণ ও গবেষণা করা, তার রূপান্তর বা বিলুপ্তির সম্ভাবনা অন্বেষণ করা</td><td>জীবন ব্যবস্থাপনা ব্যুরো + গবেষণা প্রতিষ্ঠান</td></tr></tbody></table><h3 id="৪-বিচ্ছিন্নতার-পর-অন্ধকার-আত্মার-বসতি-স্থাপন" tabindex="-1">(৪) বিচ্ছিন্নতার পর অন্ধকার আত্মার বসতি স্থাপন <a class="header-anchor" href="#৪-বিচ্ছিন্নতার-পর-অন্ধকার-আত্মার-বসতি-স্থাপন" aria-label="Permalink to &quot;(৪) বিচ্ছিন্নতার পর অন্ধকার আত্মার বসতি স্থাপন&quot;">​</a></h3><p>বিচ্ছিন্ন অন্ধকার আত্মা নিম্নলিখিত পদ্ধতিতে বসতি স্থাপন করা হয়:</p><ul><li><strong>আত্মা পাত্র</strong>: অন্ধকার আত্মা বিশেষ আত্মা কন্টেইনমেন্ট পাত্রে বসতি স্থাপন করা হয়, পাত্রে শক্তি স্ক্রিনিং, চেতনা দমন, নিরাপত্তা লক ইত্যাদি যন্ত্র সজ্জিত।</li><li><strong>সংরক্ষণ সুবিধা</strong>: পাত্র বিশেষ আত্মা সংরক্ষণ সুবিধায় সংরক্ষণ করা হয়, সুবিধা সর্বোচ্চ স্তরের নিরাপত্তা ব্যবস্থাপনা প্রয়োগ করে।</li><li><strong>ক্রমাগত পর্যবেক্ষণ</strong>: অন্ধকার আত্মার চেতনা কার্যকলাপ, শক্তি ওঠানামা 24 ঘণ্টা ক্রমাগত পর্যবেক্ষণ করা হয়।</li><li><strong>গবেষণা ব্যবহার</strong>: কঠোর নৈতিক পর্যালোচনার অধীনে, অন্ধকার আত্মার উপর বৈজ্ঞানিক গবেষণা করা যায়, অতল গহ্বর শক্তির মূল সত্তা ও বিশুদ্ধকরণ পদ্ধতি অন্বেষণ করা যায়।</li><li><strong>চূড়ান্ত নিষ্পত্তি</strong>: গবেষণার ফলাফল ও ঝুঁকি মূল্যায়ন অনুযায়ী, অন্ধকার আত্মার চূড়ান্ত নিষ্পত্তি সিদ্ধান্ত নেওয়া হয় — অ-বিনাশকারী অস্তিত্বে রূপান্তর, দীর্ঘমেয়াদী সংরক্ষণ, বা বিশুদ্ধকরণ বিলুপ্তি।</li></ul><h3 id="৫-বিচ্ছিন্নতার-ঝুঁকি-ও-মোকাবেলা" tabindex="-1">(৫) বিচ্ছিন্নতার ঝুঁকি ও মোকাবেলা <a class="header-anchor" href="#৫-বিচ্ছিন্নতার-ঝুঁকি-ও-মোকাবেলা" aria-label="Permalink to &quot;(৫) বিচ্ছিন্নতার ঝুঁকি ও মোকাবেলা&quot;">​</a></h3><p>আত্মা বিচ্ছিন্নতা অস্ত্রোপচারে নিম্নলিখিত ঝুঁকি রয়েছে, মোকাবেলা পরিকল্পনা তৈরি করতে হবে:</p><table tabindex="0"><thead><tr><th>ঝুঁকি</th><th>মোকাবেলা পরিকল্পনা</th></tr></thead><tbody><tr><td>বিচ্ছিন্নতা প্রক্রিয়ায় মূল মালিক আত্মা ক্ষতিগ্রস্ত</td><td>বিচ্ছিন্নতার পূর্বে আত্মা শক্তিশালীকরণ করা, বিচ্ছিন্নতার সময় উচ্চকক্ষের সাধক সম্পূর্ণ পথে সাহায্য করা</td></tr><tr><td>বিচ্ছিন্নতার পর মূল মালিকের শরীর অভিযোজন করতে পারে না</td><td>বিচ্ছিন্নতার পর সম্পূর্ণ শরীর পুনর্বাসন ও আত্মা স্থিতিশীলকরণ চিকিৎসা করা</td></tr><tr><td>বিচ্ছিন্নতা প্রক্রিয়ায় অন্ধকার আত্মা পালিয়ে যায়</td><td>বিচ্ছিন্নতা সর্বোচ্চ স্তরের নিরাপত্তা সুবিধায় করা হয়, বহু কন্টেইনমেন্ট যন্ত্র সজ্জিত</td></tr><tr><td>বিচ্ছিন্নতা অসম্পূর্ণ, অন্ধকার শক্তি অবশিষ্ট থাকে</td><td>বিচ্ছিন্নতার পর গভীর বিশুদ্ধকরণ চিকিৎসা করা, অবশিষ্ট অন্ধকার শক্তি পরিষ্কার করা</td></tr><tr><td>মূল মালিক আত্মা বিচ্ছিন্নতার পর মানসিক আঘাত পায়</td><td>দীর্ঘমেয়াদী মানসিক পরামর্শ ও মানসিক চিকিৎসা প্রদান করা</td></tr></tbody></table><h2 id="৪-তৃতীয়-শ্রেণী-সীলমোহর-পর্যবেক্ষণ-ধরনের-নিষ্পত্তি" tabindex="-1">৪. তৃতীয় শ্রেণী: সীলমোহর পর্যবেক্ষণ ধরনের নিষ্পত্তি <a class="header-anchor" href="#৪-তৃতীয়-শ্রেণী-সীলমোহর-পর্যবেক্ষণ-ধরনের-নিষ্পত্তি" aria-label="Permalink to &quot;৪. তৃতীয় শ্রেণী: সীলমোহর পর্যবেক্ষণ ধরনের নিষ্পত্তি&quot;">​</a></h2><p>সীলমোহর পর্যবেক্ষণ ধরনের নিষ্পত্তি মিলন ও বিচ্ছিন্নতা দুটোই করা যায় না, কিন্তু মূল মালিক আত্মা বিদ্যমান এবং অবিলম্বে বিলুপ্তির শর্ত নেই এমন অন্ধকার প্রতিস্থাপনকারীদের জন্য প্রযোজ্য, সীলমোহর পদ্ধতির মাধ্যমে তার বিপজ্জনকতা নিয়ন্ত্রণ করে, দীর্ঘমেয়াদী পর্যবেক্ষণ ও ক্রমাগত মূল্যায়ন করা হয়।</p><h3 id="১-প্রযোজ্য-শর্ত-2" tabindex="-1">(১) প্রযোজ্য শর্ত <a class="header-anchor" href="#১-প্রযোজ্য-শর্ত-2" aria-label="Permalink to &quot;(১) প্রযোজ্য শর্ত&quot;">​</a></h3><p>১. অন্ধকার প্রতিস্থাপনকারী চতুর্থ পর্যায়ে (অন্ধকার প্রধানকাল), মূল মালিক আত্মা গভীরভাবে দমন করা হয়েছে কিন্তু এখনও বিলীন হয়নি। ২. মিলন ও বিচ্ছিন্নতা দুটোই প্রযুক্তিগত সম্ভাব্যতা নেই বা ঝুঁকি অত্যন্ত বেশি। ৩. অন্ধকার প্রতিস্থাপনকারীর ঝুঁকির মাত্রা তৃতীয় স্তরে (উচ্চ ঝুঁকি), কিন্তু এখনও অবিলম্বে বিলুপ্তি করার মাত্রায় পৌঁছায়নি। ৪. মূল মালিক আত্মার এখনও ক্ষীণ পুনরুদ্ধারের সম্ভাবনা রয়েছে, সুযোগের জন্য সময় ও শর্তের অপেক্ষা করা প্রয়োজন। ৫. দ্বৈত আত্মা নৈতিক পর্যালোচনা কমিটি সীলমোহর পরিকল্পনা পর্যালোচনা ও অনুমোদন করেছে।</p><h3 id="২-নিষ্পত্তির-লক্ষ্য-2" tabindex="-1">(২) নিষ্পত্তির লক্ষ্য <a class="header-anchor" href="#২-নিষ্পত্তির-লক্ষ্য-2" aria-label="Permalink to &quot;(২) নিষ্পত্তির লক্ষ্য&quot;">​</a></h3><p>সীলমোহর পদ্ধতির মাধ্যমে অন্ধকার আত্মার শক্তি ও কার্যকলাপ দমন করা, অন্ধকার প্রতিস্থাপনকারীর বিপজ্জনকতা নিয়ন্ত্রণ করা, একই সাথে মূল মালিক আত্মা সম্পূর্ণরূপে বিনষ্ট হওয়া থেকে রক্ষা করা, দীর্ঘমেয়াদী পর্যবেক্ষণে পুনরুদ্ধার বা নিষ্পত্তির সময়ের পরিপক্কতার অপেক্ষা করা।</p><h3 id="৩-সীলমোহর-পদ্ধতি" tabindex="-1">(৩) সীলমোহর পদ্ধতি <a class="header-anchor" href="#৩-সীলমোহর-পদ্ধতি" aria-label="Permalink to &quot;(৩) সীলমোহর পদ্ধতি&quot;">​</a></h3><p>অন্ধকার প্রতিস্থাপনকারীর শক্তির মাত্রা ও বৈশিষ্ট্য অনুযায়ী, নিম্নলিখিত সীলমোহর পদ্ধতি বেছে নেওয়া হয়:</p><table tabindex="0"><thead><tr><th>সীলমোহর পদ্ধতি</th><th>নীতি</th><th>প্রযোজ্য বস্তু</th></tr></thead><tbody><tr><td>শক্তি সীলমোহর</td><td>সীলমোহর মন্ত্র বা সীলমোহর যন্ত্র ব্যবহার করে অন্ধকার শক্তির প্রবাহ ও আউটপুট দমন করা</td><td>মাঝারি নিম্ন শক্তির মাত্রার অন্ধকার প্রতিস্থাপনকারী</td></tr><tr><td>স্থান সীলমোহর</td><td>অন্ধকার প্রতিস্থাপনকারীকে স্বাধীন বিচ্ছিন্ন স্থানে সীলমোহর করা, বাইরের বিশ্বের সাথে যোগাযোগ কাটা</td><td>উচ্চ শক্তির মাত্রা বা সংক্রামক বৈশিষ্ট্যের অন্ধকার প্রতিস্থাপনকারী</td></tr><tr><td>চেতনা সীলমোহর</td><td>অন্ধকার আত্মার চেতনা কার্যকলাপ দমন করা, তাকে নিদ্রা বা অর্ধ-নিদ্রা অবস্থায় রাখা</td><td>চেতনা সক্রিয়, আত্মা আক্রমণ ক্ষমতা সম্পন্ন অন্ধকার প্রতিস্থাপনকারী</td></tr><tr><td>বহু সীলমোহর</td><td>একই সাথে বহু সীলমোহর পদ্ধতি ব্যবহার করা, বহু সুরক্ষা গঠন করা</td><td>অত্যন্ত উচ্চ শক্তির মাত্রা বা বহু বিপজ্জনক বৈশিষ্ট্যের অন্ধকার প্রতিস্থাপনকারী</td></tr><tr><td>অ্যাঙ্কর সীলমোহর</td><td>অ্যাঙ্কর শক্তির মূল বৈশিষ্ট্য ব্যবহার করে সীলমোহর করা, এটি সবচেয়ে শক্তিশালী সীলমোহর পদ্ধতি</td><td>মহাজাগতিক স্তরের বিপজ্জনক অন্ধকার প্রতিস্থাপনকারী</td></tr></tbody></table><h3 id="৪-নিষ্পত্তির-পদক্ষেপ" tabindex="-1">(৪) নিষ্পত্তির পদক্ষেপ <a class="header-anchor" href="#৪-নিষ্পত্তির-পদক্ষেপ" aria-label="Permalink to &quot;(৪) নিষ্পত্তির পদক্ষেপ&quot;">​</a></h3><table tabindex="0"><thead><tr><th>পদক্ষেপ</th><th>নাম</th><th>নির্দিষ্ট বিষয়বস্তু</th><th>দায়িত্বপ্রাপ্ত প্রতিষ্ঠান</th></tr></thead><tbody><tr><td>প্রথম পদক্ষেপ</td><td>নৈতিক পর্যালোচনা</td><td>দ্বৈত আত্মা নৈতিক পর্যালোচনা কমিটি সীলমোহর পরিকল্পনার পর্যালোচনা করে, সীলমোহরের প্রয়োজনীয়তা ও উপযুক্ততা কনফার্ম করে</td><td>দ্বৈত আত্মা নৈতিক পর্যালোচনা কমিটি</td></tr><tr><td>দ্বিতীয় পদক্ষেপ</td><td>সীলমোহর প্রস্তুতি</td><td>সীলমোহর মন্ত্র/যন্ত্র/স্থান প্রস্তুত করা, সীলমোহরে প্রয়োজনীয় শক্তি ও কর্মী বিনিয়োগ করা</td><td>প্রযুক্তি দল + উচ্চকক্ষের সাধক</td></tr><tr><td>তৃতীয় পদক্ষেপ</td><td>বশীভূত নিয়ন্ত্রণ</td><td>নিরাপত্তা দলের সহযোগিতায় অন্ধকার প্রতিস্থাপনকারীকে বশীভূত করা, সীলমোহর প্রক্রিয়ায় দুর্ঘটনা না হওয়া নিশ্চিত করা</td><td>নিরাপত্তা বিভাগ + উচ্চকক্ষের সাধক</td></tr><tr><td>চতুর্থ পদক্ষেপ</td><td>সীলমোহর প্রয়োগ</td><td>সীলমোহর পরিকল্পনা অনুযায়ী সীলমোহর প্রয়োগ করা, অন্ধকার আত্মার শক্তি ও কার্যকলাপ দমন করা</td><td>উচ্চকক্ষের সাধক + সীলমোহর বিশেষজ্ঞ</td></tr><tr><td>পঞ্চম পদক্ষেপ</td><td>সীলমোহর যাচাই</td><td>সীলমোহরের কার্যকারিতা ও স্থিতিশীলতা যাচাই করা, অন্ধকার প্রতিস্থাপনকারীর বিপজ্জনকতা নিয়ন্ত্রিত হয়েছে কনফার্ম করা</td><td>প্রযুক্তি দল + পর্যবেক্ষণ দল</td></tr><tr><td>ষষ্ঠ পদক্ষেপ</td><td>স্থানান্তর বসতি স্থাপন</td><td>সীলমোহর后的 অন্ধকার প্রতিস্থাপনকারীকে বিশেষ সীলমোহর পর্যবেক্ষণ সুবিধায় স্থানান্তর করা</td><td>নিরাপত্তা বিভাগ + জীবন ব্যবস্থাপনা ব্যুরো</td></tr><tr><td>সপ্তম পদক্ষেপ</td><td>ক্রমাগত পর্যবেক্ষণ</td><td>সীলমোহর অবস্থা 24 ঘণ্টা ক্রমাগত পর্যবেক্ষণ করা, নিয়মিত সীলমোহরের স্থিতিশীলতা পরীক্ষা করা</td><td>পর্যবেক্ষণ দল</td></tr><tr><td>অষ্টম পদক্ষেপ</td><td>নিয়মিত পুনর্মূল্যায়ন</td><td>প্রতি ছয় মাসে একবার সম্পূর্ণ পুনর্মূল্যায়ন করা, মূল মালিক আত্মার অবস্থা, অন্ধকার আত্মার বৈশিষ্ট্য, সীলমোহরের স্থিতিশীলতা মূল্যায়ন করা, নিষ্পত্তি ধরন সামঞ্জস্যের সম্ভাবনা রয়েছে কিনা সিদ্ধান্ত নেওয়া</td><td>শনাক্তকরণ বিশেষজ্ঞ দল + নৈতিক পর্যালোচনা কমিটি</td></tr><tr><td>নবম পদক্ষেপ</td><td>সীলমোহর রক্ষণাবেক্ষণ</td><td>নিয়মিত সীলমোহর রক্ষণাবেক্ষণ ও শক্তিশালীকরণ করা, সীলমোহরের দুর্বলতা বা ক্ষতি প্রতিরোধ করা</td><td>সীলমোহর বিশেষজ্ঞ + প্রযুক্তি দল</td></tr></tbody></table><h3 id="৫-সীলমোহর-পর্যবেক্ষণ-সুবিধার-মানদণ্ড" tabindex="-1">(৫) সীলমোহর পর্যবেক্ষণ সুবিধার মানদণ্ড <a class="header-anchor" href="#৫-সীলমোহর-পর্যবেক্ষণ-সুবিধার-মানদণ্ড" aria-label="Permalink to &quot;(৫) সীলমোহর পর্যবেক্ষণ সুবিধার মানদণ্ড&quot;">​</a></h3><ul><li><strong>নির্বাচন</strong>: সীলমোহর পর্যবেক্ষণ সুবিধা ভূতাত্ত্বিকভাবে স্থিতিশীল, শক্তি পরিবেশ স্থিতিশীল, জনসংখ্যা বিরল প্রত্যন্ত অঞ্চলে, বা স্বাধীন বিচ্ছিন্ন মাতৃকায় নির্বাচন করা হয়।</li><li><strong>নির্মাণ</strong>: সুবিধা বহু সুরক্ষা কাঠামো ব্যবহার করে, যার মধ্যে পদার্থিক বাধা, শক্তি বাধা, স্থান লক তিন স্তরের সুরক্ষা অন্তর্ভুক্ত।</li><li><strong>যন্ত্র</strong>: উচ্চ নির্ভুলতার সীলমোহর পর্যবেক্ষণ যন্ত্র, স্বয়ংক্রিয় শক্তিশালীকরণ সিস্টেম, জরুরি প্রতিক্রিয়া সিস্টেম, বিকল্প শক্তি সিস্টেম সজ্জিত।</li><li><strong>কর্মী</strong>: 24 ঘণ্টা ডিউটি সিস্টেম প্রয়োগ করা, সীলমোহর বিশেষজ্ঞ, পর্যবেক্ষণ কর্মী, নিরাপত্তা রক্ষী কর্মী, জরুরি নিষ্পত্তি কর্মী নিযুক্ত করা।</li><li><strong>জরুরি</strong>: সীলমোহর ক্ষতি, অন্ধকার আত্মা পালিয়ে যাওয়া, মূল মালিক আত্মা বিলীন ইত্যাদি বিভিন্ন জরুরি পরিকল্পনা তৈরি করা, নিয়মিত অনুশীলন করা।</li></ul><h3 id="৬-সীলমোহরের-মুক্তি-ও-রূপান্তর" tabindex="-1">(৬) সীলমোহরের মুক্তি ও রূপান্তর <a class="header-anchor" href="#৬-সীলমোহরের-মুক্তি-ও-রূপান্তর" aria-label="Permalink to &quot;(৬) সীলমোহরের মুক্তি ও রূপান্তর&quot;">​</a></h3><p>নিম্নলিখিত অবস্থায়, সীলমোহর মুক্ত বা নিষ্পত্তি ধরন রূপান্তর করা যায়:</p><ul><li><strong>মূল মালিক পুনরুদ্ধার</strong>: মূল মালিক আত্মা সীলমোহরের সময় ধীরে ধীরে পুনরুদ্ধার করে, বিচ্ছিন্নতা বা মিলনের শর্ত প্রাপ্ত হলে, সীলমোহর মুক্ত করে বিচ্ছিন্নতা বসতি স্থাপন ধরন বা মিলন সিম্বায়োসিস ধরনে রূপান্তর করা যায়।</li><li><strong>অন্ধকার রূপান্তর</strong>: অন্ধকার আত্মা সীলমোহরের সময় রূপান্তরের সম্ভাবনা প্রদর্শন করলে, সীলমোহর মুক্ত করে নিয়ন্ত্রিত পরিবেশে রূপান্তরের চেষ্টা করা যায়।</li><li><strong>সীলমোহর ব্যর্থ</strong>: সীলমোহরে মেরামত করা অসম্ভব ক্ষতি বা দুর্বলতা দেখা দিলে, এবং অন্ধকার প্রতিস্থাপনকারীর বিপজ্জনকতা অনিয়ন্ত্রিত হলে, বিলুপ্তি ধরনের নিষ্পত্তিতে রূপান্তর করা যায়।</li><li><strong>মূল মালিক বিলীন</strong>: মূল মালিক আত্মা সীলমোহরের সময় সম্পূর্ণরূপে বিলীন হয়ে গেলে, অন্ধকার প্রতিস্থাপনকারী বিশুদ্ধ অন্ধকার অস্তিত্বে পরিণত হয়, তার বিপজ্জনকতা অনুযায়ী বিলুপ্তি ধরনে রূপান্তর বা চালিয়ে সীলমোহর করা যায়।</li></ul><h2 id="৫-চতুর্থ-শ্রেণী-বিলুপ্তি-ধরনের-নিষ্পত্তি" tabindex="-1">৫. চতুর্থ শ্রেণী: বিলুপ্তি ধরনের নিষ্পত্তি <a class="header-anchor" href="#৫-চতুর্থ-শ্রেণী-বিলুপ্তি-ধরনের-নিষ্পত্তি" aria-label="Permalink to &quot;৫. চতুর্থ শ্রেণী: বিলুপ্তি ধরনের নিষ্পত্তি&quot;">​</a></h2><p>বিলুপ্তি ধরনের নিষ্পত্তি হলো চার শাখার মধ্যে সবচেয়ে কঠোর নিষ্পত্তির পদ্ধতি, যা রক্ষা করা অসম্ভব, বিপজ্জনকতা অত্যন্ত বেশি এমন অন্ধকার প্রতিস্থাপনকারীদের জন্য প্রযোজ্য, অন্ধকার আত্মা বিনাশ (এবং প্রয়োজনে সম্পূর্ণ শরীর বিনাশ) করার মাধ্যমে হুমকি দূর করা হয়।</p><h3 id="১-প্রযোজ্য-শর্ত-3" tabindex="-1">(১) প্রযোজ্য শর্ত <a class="header-anchor" href="#১-প্রযোজ্য-শর্ত-3" aria-label="Permalink to &quot;(১) প্রযোজ্য শর্ত&quot;">​</a></h3><p>বিলুপ্তি ধরনের নিষ্পত্তি নিম্নলিখিত পরিস্থিতিতে প্রযোজ্য:</p><p>১. অন্ধকার প্রতিস্থাপনকারী পঞ্চম পর্যায়ে (সম্পূর্ণ প্রতিস্থাপনকাল), মূল মালিক আত্মা সম্পূর্ণরূপে বিলীন হয়ে গেছে, শরীর অন্ধকার আত্মা দ্বারা সম্পূর্ণরূপে নিয়ন্ত্রিত, বিশুদ্ধ অন্ধকার অস্তিত্বে পরিণত হয়েছে। ২. অন্ধকার প্রতিস্থাপনকারী চতুর্থ পর্যায়ে, মূল মালিক আত্মা বিদ্যমান থাকলেও পুনরুদ্ধার করা অসম্ভব, মিলন, বিচ্ছিন্নতা, সীলমোহর সবই সম্ভব নয়, এবং তার বিপজ্জনকতা ক্রমাগত বাড়ছে। ৩. অন্ধকার প্রতিস্থাপনকারীর ঝুঁকির মাত্রা চতুর্থ স্তরে (অত্যন্ত উচ্চ ঝুঁকি), মহাজাগতিক স্তরের বিনাশকারীতা রয়েছে, সরাসরি সভ্যতার বেঁচে থাকাকে হুমকি দিচ্ছে, অন্য নিষ্পত্তি পদ্ধতি সবই তার হুমকি নিয়ন্ত্রণ করতে পারছে না। ৪. সীলমোহর পর্যবেক্ষণ ধরনের নিষ্পত্তিতে সীলমোহর ব্যর্থ হয়েছে এবং পুনরায় সীলমোহর করা সম্ভব নয়, অন্ধকার প্রতিস্থাপনকারীর বিপজ্জনকতা অনিয়ন্ত্রিত। ৫. দ্বৈত আত্মা নৈতিক পর্যালোচনা কমিটি বিলুপ্তি পরিকল্পনা পর্যালোচনা ও অনুমোদন (অত্যন্ত উচ্চ ঝুঁকির জরুরি পরিস্থিতিতে প্রথমে নিষ্পত্তি করে পরে অনুমোদনের জন্য পাঠানো যায়)।</p><h3 id="২-বিলুপ্তির-নীতি" tabindex="-1">(২) বিলুপ্তির নীতি <a class="header-anchor" href="#২-বিলুপ্তির-নীতি" aria-label="Permalink to &quot;(২) বিলুপ্তির নীতি&quot;">​</a></h3><p>বিলুপ্তি ধরনের নিষ্পত্তি জীবনের বিনাশ জড়িত, অবশ্যই নিম্নলিখিত নীতি কঠোরভাবে অনুসরণ করতে হবে:</p><ul><li><strong>শেষ উপায় নীতি</strong>: বিলুপ্তি অবশ্যই অন্য সব নিষ্পত্তি পদ্ধতি সম্ভব না হওয়ার পরের শেষ উপায় হতে হবে।</li><li><strong>আনুপাতিকতা নীতি</strong>: বিলুপ্তির তীব্রতা হুমকির মাত্রার সাথে মানানসই হতে হবে, অতিরিক্ত বল প্রয়োগ নিষিদ্ধ।</li><li><strong>সর্বনিম্ন যন্ত্রণা নীতি</strong>: বিলুপ্তি যতটা সম্ভব ব্যথাহীন, দ্রুত পদ্ধতি অবলম্বন করা উচিত, অন্ধকার আত্মা (এবং মূল মালিক আত্মা, যদি বিদ্যমান থাকে) এর যন্ত্রণা কমাতে হবে।</li><li><strong>মূল মালিককে সম্মান নীতি</strong>: মূল মালিক আত্মা বিদ্যমান থাকলে, বিলুপ্তির পূর্বে যতটা সম্ভব মূল মালিক আত্মাকে সচেতন ও মর্যাদাপূর্ণ রাখা উচিত, প্রয়োজনে মূল মালিককে বন্ধু-বান্ধবদের সাথে বিদায় নিতে দেওয়া উচিত।</li><li><strong>সম্পূর্ণ রেকর্ড নীতি</strong>: বিলুপ্তি প্রক্রিয়া সম্পূর্ণরূপে রেকর্ড করা, সম্পূর্ণ ফাইল তৈরি করা, পর্যালোচনা ও ট্র্যাকিংয়ের জন্য প্রস্তুত রাখা।</li><li><strong>পরবর্তী পর্যালোচনা নীতি</strong>: বিলুপ্তি সম্পন্নের পর পরবর্তী পর্যালোচনা করা, বিলুপ্তির প্রয়োজনীয়তা ও উপযুক্ততা মূল্যায়ন করা, অভিজ্ঞতা ও শিক্ষা সংগ্রহ করা।</li></ul><h3 id="৩-বিলুপ্তির-পদ্ধতি" tabindex="-1">(৩) বিলুপ্তির পদ্ধতি <a class="header-anchor" href="#৩-বিলুপ্তির-পদ্ধতি" aria-label="Permalink to &quot;(৩) বিলুপ্তির পদ্ধতি&quot;">​</a></h3><p>অন্ধকার প্রতিস্থাপনকারীর শক্তির মাত্রা ও বৈশিষ্ট্য অনুযায়ী, নিম্নলিখিত বিলুপ্তির পদ্ধতি বেছে নেওয়া হয়:</p><table tabindex="0"><thead><tr><th>বিলুপ্তির পদ্ধতি</th><th>নীতি</th><th>প্রযোজ্য বস্তু</th></tr></thead><tbody><tr><td>পবিত্র আলো বিশুদ্ধকরণ বিলুপ্তি</td><td>উচ্চ তীব্রতার পবিত্র আলো শক্তি ব্যবহার করে অন্ধকার আত্মা বিশুদ্ধ করা, তাকে আলোতে বিলীন করা</td><td>মাঝারি নিম্ন শক্তির মাত্রার অন্ধকার প্রতিস্থাপনকারী</td></tr><tr><td>আত্মা বিনাশ মন্ত্র</td><td>সরাসরি অন্ধকার আত্মার আত্মা কোরকে আক্রমণ ও বিনাশ করা, তাকে সম্পূর্ণরূপে বিলীন করা</td><td>উচ্চ শক্তির মাত্রার অন্ধকার প্রতিস্থাপনকারী</td></tr><tr><td>স্থান নির্বাসন বিলুপ্তি</td><td>অন্ধকার প্রতিস্থাপনকারীকে শূন্য স্থান বা সময়ের শেষ প্রান্তে নির্বাসন করা, স্থান-কাল ক্ষয়ে বিলীন করা</td><td>শক্তিশালী পদার্থিক প্রতিরক্ষা সম্পন্ন অন্ধকার প্রতিস্থাপনকারী</td></tr><tr><td>অ্যাঙ্কর মূল বিলুপ্তি</td><td>অ্যাঙ্করের মূল শক্তি আহ্বান করা, অন্ধকার প্রতিস্থাপনকারীকে বিশ্লেষণ করে মহাজাগতিক মূলতে ফিরিয়ে দেওয়া</td><td>মহাজাগতিক স্তরের বিপজ্জনক অন্ধকার প্রতিস্থাপনকারী</td></tr><tr><td>বহু মাতৃকা শক্তিশালী যৌথ বিলুপ্তি</td><td>বহু মাতৃকার সর্বোচ্চ শক্তিশালী ব্যক্তি যৌথভাবে হস্তক্ষেপ করে, পরম শক্তি দিয়ে অন্ধকার প্রতিস্থাপনকারীকে দমন ও বিনাশ করা</td><td>অত্যন্ত উচ্চ শক্তির মাত্রার অন্ধকার প্রতিস্থাপনকারী</td></tr><tr><td>স্ব-বিস্ফোরণ প্ররোচন বিলুপ্তি</td><td>কঠোর নিয়ন্ত্রণে অন্ধকার প্রতিস্থাপনকারীর অন্ধকার শক্তির স্ব-বিস্ফোরণ প্ররোচন করা, শক্তি বিস্ফোরণে বিলীন করা</td><td>শক্তি অস্থির অন্ধকার প্রতিস্থাপনকারী</td></tr></tbody></table><h3 id="৪-নিষ্পত্তির-পদক্ষেপ-1" tabindex="-1">(৪) নিষ্পত্তির পদক্ষেপ <a class="header-anchor" href="#৪-নিষ্পত্তির-পদক্ষেপ-1" aria-label="Permalink to &quot;(৪) নিষ্পত্তির পদক্ষেপ&quot;">​</a></h3><table tabindex="0"><thead><tr><th>পদক্ষেপ</th><th>নাম</th><th>নির্দিষ্ট বিষয়বস্তু</th><th>দায়িত্বপ্রাপ্ত প্রতিষ্ঠান</th></tr></thead><tbody><tr><td>প্রথম পদক্ষেপ</td><td>নৈতিক পর্যালোচনা/জরুরি অনুমোদন</td><td>স্বাভাবিক পরিস্থিতিতে দ্বৈত আত্মা নৈতিক পর্যালোচনা কমিটি পর্যালোচনা ও অনুমোদন করে; অত্যন্ত উচ্চ ঝুঁকির জরুরি পরিস্থিতিতে স্থানীয় সর্বোচ্চ দায়িত্বপ্রাপ্ত ব্যক্তি আদেশ দেয়, পরে অনুমোদনের জন্য পাঠানো হয়</td><td>দ্বৈত আত্মা নৈতিক পর্যালোচনা কমিটি/স্থানীয় সর্বোচ্চ দায়িত্বপ্রাপ্ত ব্যক্তি</td></tr><tr><td>দ্বিতীয় পদক্ষেপ</td><td>পরিকল্পনা তৈরি</td><td>বিস্তারিত বিলুপ্তি পরিকল্পনা তৈরি করা, যার মধ্যে বিলুপ্তির পদ্ধতি, শক্তি বিনিয়োগ, নিরাপত্তা ব্যবস্থা, জরুরি পরিকল্পনা, পরিবেশ প্রভাব মূল্যায়ন অন্তর্ভুক্ত</td><td>যুদ্ধ কমান্ড কেন্দ্র + প্রযুক্তি বিশেষজ্ঞ দল</td></tr><tr><td>তৃতীয় পদক্ষেপ</td><td>শক্তি একত্রীকরণ</td><td>বিলুপ্তি বাস্তবায়নে প্রয়োজনীয় সাধক, প্রযুক্তি কর্মী, সরঞ্জাম ও শক্তি সম্পদ একত্রীকরণ করা</td><td>নিরাপত্তা বিভাগ + উচ্চকক্ষের সাধক</td></tr><tr><td>চতুর্থ পদক্ষেপ</td><td>অঞ্চল অবরোধ</td><td>বিলুপ্তি অঞ্চল অবরোধ করা, আশেপাশের লোকজন সরিয়ে নেওয়া, নিরাপত্তা সতর্কতা সীমা সেট করা</td><td>নিরাপত্তা বিভাগ + স্থানীয় সরকার</td></tr><tr><td>পঞ্চম পদক্ষেপ</td><td>বশীভূত দমন</td><td>প্রথমে দমন শক্তি দিয়ে অন্ধকার প্রতিস্থাপনকারীর কর্মকাণ্ড নিয়ন্ত্রণ করা, তার পালিয়ে যাওয়া বা আরও বড় বিনাশ সৃষ্টি করা প্রতিরোধ করা</td><td>উচ্চকক্ষের সাধক + নিরাপত্তা বাহিনী</td></tr><tr><td>ষষ্ঠ পদক্ষেপ</td><td>বিলুপ্তি প্রয়োগ</td><td>বিলুপ্তি পরিকল্পনা অনুযায়ী বিলুপ্তি প্রয়োগ করা, প্রক্রিয়া সম্পূর্ণরূপে পর্যবেক্ষণ করা, অস্বাভাবিকতা দেখা দিলে অবিলম্বে জরুরি পরিকল্পনা শুরু করা</td><td>উচ্চকক্ষের সাধক + প্রযুক্তি দল</td></tr><tr><td>সপ্তম পদক্ষেপ</td><td>বিলীন নিশ্চিতকরণ</td><td>অন্ধকার আত্মা (এবং শরীর) সম্পূর্ণরূপে বিলীন হয়েছে কনফার্ম করা, শক্তি অবশিষ্ট বা আত্মার টুকরা আছে কিনা সনাক্ত করা</td><td>পর্যবেক্ষণ দল + শনাক্তকরণ বিশেষজ্ঞ দল</td></tr><tr><td>অষ্টম পদক্ষেপ</td><td>পরিবেশ পুনরুদ্ধার</td><td>বিলুপ্তি অঞ্চলের পরিবেশ পুনরুদ্ধার করা, অন্ধকার শক্তি অবশিষ্ট পরিষ্কার করা, পরিবেশগত ভারসাম্য পুনরুদ্ধার করা</td><td>পরিবেশ বিভাগ</td></tr><tr><td>নবম পদক্ষেপ</td><td>পরবর্তী ব্যবস্থা</td><td>মূল মালিকের বন্ধু-বান্ধবদেরকে জানানো (যদি মূল মালিক বিলীন হয়ে থাকে), মূল মালিকের সম্পত্তি ব্যবস্থাপনা করা, মানসিক পরামর্শ প্রদান করা</td><td>নাগরিক ব্যবস্থাপনা বিভাগ + মানসিক পরামর্শদাতা</td></tr><tr><td>দশম পদক্ষেপ</td><td>ফাইল সংরক্ষণ ও পরবর্তী পর্যালোচনা</td><td>বিলুপ্তি সম্পূর্ণ প্রক্রিয়ার রেকর্ড সংরক্ষণ করা, পরবর্তী পর্যালোচনা করা, প্রয়োজনীয়তা ও উপযুক্ততা মূল্যায়ন করা</td><td>জীবন ব্যবস্থাপনা ব্যুরো + নৈতিক পর্যালোচনা কমিটি</td></tr></tbody></table><h3 id="৫-জরুরি-বিলুপ্তি-প্রক্রিয়া" tabindex="-1">(৫) জরুরি বিলুপ্তি প্রক্রিয়া <a class="header-anchor" href="#৫-জরুরি-বিলুপ্তি-প্রক্রিয়া" aria-label="Permalink to &quot;(৫) জরুরি বিলুপ্তি প্রক্রিয়া&quot;">​</a></h3><p>চতুর্থ স্তর (অত্যন্ত উচ্চ ঝুঁকি), সরাসরি সভ্যতার বেঁচে থাকাকে হুমকি দেওয়া অন্ধকার প্রতিস্থাপনকারীর জন্য, জরুরি বিলুপ্তি প্রক্রিয়া প্রযোজ্য:</p><p>১. স্থানীয় সর্বোচ্চ স্তরের দায়িত্বপ্রাপ্ত ব্যক্তি সরাসরি জরুরি বিলুপ্তি শুরু করার আদেশ দিতে পারেন, পূর্বে নৈতিক পর্যালোচনার প্রয়োজন নেই, কিন্তু বিলুপ্তির পর 24 ঘণ্টার মধ্যে দ্বৈত আত্মা নৈতিক পর্যালোচনা কমিটিতে রিপোর্ট করে রেকর্ড করাতে হবে। ২. জরুরি বিলুপ্তিতে সভ্যতার সর্বোচ্চ স্তরের অস্ত্র ও শক্তি সম্পদ ব্যবহার করা যায়, যার মধ্যে অ্যাঙ্কর শক্তির কেন্দ্রীভূত আহ্বান ও বহু মাতৃকার সর্বোচ্চ শক্তিশালী ব্যক্তিদের যৌথ হস্তক্ষেপ অন্তর্ভুক্ত। ৩. জরুরি বিলুপ্তির অগ্রাধিকার লক্ষ্য হলো হুমকি দূর করা, জীবন ও সভ্যতার নিরাপত্তা রক্ষা করা, বিলুপ্তির পদ্ধতির &quot;মার্জনীয়তা&quot; বা &quot;ব্যথাহীনতা&quot; অর্জন করা নয় (কিন্তু তবুও যতটা সম্ভব সংলগ্ন ক্ষতি কমাতে হবে)। ৪. জরুরি বিলুপ্তির পর সম্পূর্ণ পরিবেশ মূল্যায়ন ও পুনরুদ্ধার করা উচিত, অন্ধকার শক্তি অবশিষ্ট ও গৌণ বিপর্যয় প্রতিরোধ করতে হবে। ৫. জরুরি বিলুপ্তির কেস অবশ্যই পরবর্তী পুনর্বিবেচনা ও গভীর বিশ্লেষণ করতে হবে, অভিজ্ঞতা ও শিক্ষা সংগ্রহ করতে হবে, সতর্কতা ও নিষ্পত্তি প্রক্রিয়া উন্নত করতে হবে।</p><h2 id="৬-চার-শাখা-নিষ্পত্তির-রূপান্তর-ব্যবস্থা" tabindex="-1">৬. চার শাখা নিষ্পত্তির রূপান্তর ব্যবস্থা <a class="header-anchor" href="#৬-চার-শাখা-নিষ্পত্তির-রূপান্তর-ব্যবস্থা" aria-label="Permalink to &quot;৬. চার শাখা নিষ্পত্তির রূপান্তর ব্যবস্থা&quot;">​</a></h2><p>অন্ধকার প্রতিস্থাপনকারীর নিষ্পত্তি অপরিবর্তনীয় নয়, নিষ্পত্তি প্রক্রিয়ায় পরিস্থিতির পরিবর্তন অনুযায়ী, চার শাখার মধ্যে রূপান্তর করা যায়:</p><table tabindex="0"><thead><tr><th>রূপান্তরের দিক</th><th>রূপান্তরের শর্ত</th><th>রূপান্তরের প্রক্রিয়া</th></tr></thead><tbody><tr><td>মিলন→বিচ্ছিন্নতা</td><td>মিলনের চেষ্টা ব্যর্থ হয়েছে বা মিলনের পরে গুরুতর অস্থিরতা দেখা দিয়েছে</td><td>পুনর্মূল্যায়ন, নৈতিক পর্যালোচনা অনুমোদনের পর বিচ্ছিন্নতায় রূপান্তর</td></tr><tr><td>মিলন→সীলমোহর</td><td>মিলন ব্যর্থ হয়েছে এবং বিচ্ছিন্নতা সম্ভব নয়, ঝুঁকি নিয়ন্ত্রণের প্রয়োজন</td><td>পুনর্মূল্যায়ন, নৈতিক পর্যালোচনা অনুমোদনের পর সীলমোহরে রূপান্তর</td></tr><tr><td>মিলন→বিলুপ্তি</td><td>মিলন নিয়ন্ত্রণহীন, নতুন আত্মার অনিয়ন্ত্রিত বিনাশকারীতা রয়েছে</td><td>জরুরি মূল্যায়ন, অবিলম্বে বিলুপ্তিতে রূপান্তর</td></tr><tr><td>বিচ্ছিন্নতা→সীলমোহর</td><td>বিচ্ছিন্নতা ব্যর্থ হয়েছে বা বিচ্ছিন্নতার পর মূল মালিক পুনরুদ্ধার করতে পারছে না, ঝুঁকি নিয়ন্ত্রণের প্রয়োজন</td><td>পুনর্মূল্যায়ন, নৈতিক পর্যালোচনা অনুমোদনের পর সীলমোহরে রূপান্তর</td></tr><tr><td>বিচ্ছিন্নতা→বিলুপ্তি</td><td>বিচ্ছিন্নতা প্রক্রিয়ায় অন্ধকার আত্মা পালিয়ে গেছে এবং অনিয়ন্ত্রিত</td><td>জরুরি মূল্যায়ন, অবিলম্বে বিলুপ্তিতে রূপান্তর</td></tr><tr><td>সীলমোহর→মিলন</td><td>সীলমোহরের সময় মূল মালিক আত্মা পুনরুদ্ধার করেছে, মিলনের শর্ত প্রাপ্ত</td><td>নিয়মিত পুনর্মূল্যায়নে আবিষ্কৃত, নৈতিক পর্যালোচনা অনুমোদনের পর মিলনে রূপান্তর</td></tr><tr><td>সীলমোহর→বিচ্ছিন্নতা</td><td>সীলমোহরের সময় মূল মালিক আত্মা পুনরুদ্ধার করেছে, বিচ্ছিন্নতার শর্ত প্রাপ্ত</td><td>নিয়মিত পুনর্মূল্যায়নে আবিষ্কৃত, নৈতিক পর্যালোচনা অনুমোদনের পর বিচ্ছিন্নতায় রূপান্তর</td></tr><tr><td>সীলমোহর→বিলুপ্তি</td><td>সীলমোহর ব্যর্থ হয়েছে এবং পুনরায় সীলমোহর করা সম্ভব নয়, বিপজ্জনকতা অনিয়ন্ত্রিত</td><td>জরুরি মূল্যায়ন, অবিলম্বে বিলুপ্তিতে রূপান্তর</td></tr><tr><td>বিলুপ্তি→অন্যান্য</td><td>বিলুপ্তি হলো শেষ উপায়, একবার বাস্তবায়নের পর অপরিবর্তনীয়</td><td>প্রযোজ্য নয়</td></tr></tbody></table><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>অন্ধকার প্রতিস্থাপনকারীর চার শাখা নিষ্পত্তি হলো অ্যাঙ্কর সিম্বায়োসিস সভ্যতার জীবন পরিচালনার সমগ্র সাফল্যের কাজ। মিলন সিম্বায়োসিসের সক্রিয় রক্ষা থেকে শুরু করে বিচ্ছিন্নতা বসতি স্থাপনের সুনির্দিষ্ট কাটা, সীলমোহর পর্যবেক্ষণের ধৈর্যশীল অপেক্ষা, এবং বিলুপ্তি ধরনের শেষ উপায় পর্যন্ত, চার শাখা সবচেয়ে মৃদু থেকে সবচেয়ে কঠোর পর্যন্ত একটি সম্পূর্ণ নিষ্পত্তি বর্ণালী গঠন করে, যা অন্ধকার প্রতিস্থাপনকারীর বিভিন্ন সম্ভাব্য পরিস্থিতি কভার করে। এই নিষ্পত্তি ব্যবস্থা &quot;প্রতিটি আত্মাকে পুরোপুরি চেষ্টা করে রক্ষা করা&quot; এর নৈতিক সীমানা ধরে রেখেছে, একই সাথে &quot;অনিয়ন্ত্রিত হুমকিকে দৃঢ়ভাবে দূর করা&quot; এর নিরাপত্তা সীমানা বজায় রেখেছে, যা সিম্বায়োসিস সভ্যতার জীবন নৈতিকতা ও নিরাপত্তা পরিচালনার মধ্যে সূক্ষ্ম ভারসাম্যকে প্রকাশ করেছে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>৫৭-অন্ধকার প্রতিস্থাপনকারীর উৎপত্তি ও মূল সত্তা</li><li>৫৮-দ্বৈত আত্মা নৈতিক নীতি</li><li>৫৪-অদ্ভুত জীবনের তিন শ্রেণীর নিষ্পত্তি প্রক্রিয়া</li><li>৪৮-বিচার ব্যবস্থা ও বিচার প্রক্রিয়া</li></ul>',74)])])}const q=d(h,[["render",l]]);export{c as __pageData,q as default};
